  115 static int attrnumber(const wchar_t *pw, int default_value, int type)
  116 {
  117 	int value = 0;
  118 
  119 	if ((pw == NULL) || !IsDigit09(*pw))
  120 		return default_value;
  121 
  122 	while (IsDigit09(*pw))
  123 		value = value*10 + *pw++ - '0';
  124 	if ((type == 1) && (ucd_tolower(*pw) == 's')) {
  125 		// time: seconds rather than ms
  126 		value *= 1000;
  127 	}
  128 	return value;
  129 }
