  131 static int attrcopy_utf8(char *buf, const wchar_t *pw, int len)
  132 {
  133 	// Convert attribute string into utf8, write to buf, and return its utf8 length
  134 	unsigned int c;
  135 	int ix = 0;
  136 	int n;
  137 	int prev_c = 0;
  138 
  139 	if (pw != NULL) {
  140 		while ((ix < (len-4)) && ((c = *pw++) != 0)) {
  141 			if ((c == '"') && (prev_c != '\\'))
  142 				break; // " indicates end of attribute, unless preceded by backstroke
  143 			n = utf8_out(c, &buf[ix]);
  144 			ix += n;
  145 			prev_c = c;
  146 		}
  147 	}
  148 	buf[ix] = 0;
  149 	return ix;
  150 }
  151 
  152 static int attr_prosody_value(int param_type, const wchar_t *pw, int *value_out)
  153 {
  154 	int sign = 0;
  155 	wchar_t *tail;
  156 	double value;
  157 
  158 	while (iswspace(*pw)) pw++;
  159 	if (*pw == '+') {
  160 		pw++;
  161 		sign = 1;
  162 	}
  163 	if (*pw == '-') {
  164 		pw++;
  165 		sign = -1;
  166 	}
  167 	value = (double)wcstod(pw, &tail);
  168 	if (tail == pw) {
  169 		// failed to find a number, return 100%
  170 		*value_out = 100;
  171 		return 2;
  172 	}
  173 
  174 	if (*tail == '%') {
  175 		if (sign != 0)
  176 			value = 100 + (sign * value);
  177 		*value_out = (int)value;
  178 		return 2; // percentage
  179 	}
  180 
  181 	if ((tail[0] == 's') && (tail[1] == 't')) {
  182 		double x;
  183 		// convert from semitones to a  frequency percentage
  184 		x = pow((double)2.0, (double)((value*sign)/12)) * 100;
  185 		*value_out = (int)x;
  186 		return 2; // percentage
  187 	}
  188 
  189 	if (param_type == espeakRATE) {
  190 		if (sign == 0)
  191 			*value_out = (int)(value * 100);
  192 		else
  193 			*value_out = 100 + (int)(sign * value * 100);
  194 		return 2; // percentage
  195 	}
  196 
  197 	*value_out = (int)value;
  198 	return sign;   // -1, 0, or 1
  199 }
