  100 static int dispatch_audio(short *outbuf, int length, espeak_EVENT *event)
  101 {
  102 	int a_wave_can_be_played = 1;
  103 #ifdef USE_ASYNC
  104 	if ((my_mode & ENOUTPUT_MODE_SYNCHRONOUS) == 0)
  105 		a_wave_can_be_played = fifo_is_command_enabled();
  106 #endif
  107 
  108 	switch ((int)my_mode)
  109 	{
  110 	case ENOUTPUT_MODE_SPEAK_AUDIO:
  111 	case ENOUTPUT_MODE_SPEAK_AUDIO | ENOUTPUT_MODE_SYNCHRONOUS:
  112 	{
  113 		int event_type = 0;
  114 		if (event)
  115 			event_type = event->type;
  116 
  117 		if (event_type == espeakEVENT_SAMPLERATE) {
  118 			voice_samplerate = event->id.number;
  119 
  120 			if (out_samplerate != voice_samplerate) {
  121 #ifdef HAVE_PCAUDIOLIB_AUDIO_H
  122 				if (out_samplerate != 0) {
  123 					// sound was previously open with a different sample rate
  124 					audio_object_close(my_audio);
  125 					out_samplerate = 0;
  126 #ifdef HAVE_SLEEP
  127 					sleep(1);
  128 #endif
  129 				}
  130 #endif
  131 #ifdef HAVE_PCAUDIOLIB_AUDIO_H
  132 				int error = audio_object_open(my_audio, AUDIO_OBJECT_FORMAT_S16LE, voice_samplerate, 1);
