  197 static int create_events(short *outbuf, int length, espeak_EVENT *event_list)
  198 {
  199 	int finished;
  200 	int i = 0;
  201 
  202 	// The audio data are written to the output device.
  203 	// The list of events in event_list (index: event_list_ix) is read:
  204 	// Each event is declared to the "event" object which stores them internally.
  205 	// The event object is responsible of calling the external callback
  206 	// as soon as the relevant audio sample is played.
  207 
  208 	do { // for each event
  209 		espeak_EVENT *event;
  210 		if (event_list_ix == 0)
  211 			event = NULL;
  212 		else
  213 			event = event_list + i;
  214 		finished = dispatch_audio((short *)outbuf, length, event);
  215 		length = 0; // the wave data are played once.
  216 		i++;
  217 	} while ((i < event_list_ix) && !finished);
  218 	return finished;
  219 }
